def _route(adj, ordinary, caps, logical, order=0, transit=None):
    """Route every logical edge over the physical fabric.

    Each ordered participant pair carries exactly the number of chunk copies
    that the logical trees require.  The greedy engine always takes the walk
    with the largest remaining bottleneck and splits a pair over several walks
    when a single one cannot carry the whole count.
    """
    if transit is None:
        transit = ordinary
    residual = {}
    for link, cap in caps.items():
        residual[(link, 0)] = cap
        residual[(link, 1)] = cap
    routes = []
    items = list(logical.items())
    if order == 1:
        items.sort(key=lambda kv: (kv[1], kv[0]))
    elif order == 2:
        items.sort(key=lambda kv: (-kv[1], kv[0][1], kv[0][0]))
    else:
        items.sort(key=lambda kv: (-kv[1], kv[0]))
    searches = 0
    for (u, v), demand in items:
        need = demand
        splits = 0
        while need > 0:
            searches += 1
            if searches > MAX_SEARCHES:
                return None
            chain = _shortest_path(adj, u, v, ordinary, residual, need, transit)
            if chain is not None:
                room = need
                for link, direction in chain:
                    free = residual[(link, direction)]
                    if free < room:
                        room = free
                take = need if need < room else room
            else:
                chain, room = _widest_path(adj, u, v, ordinary, residual, transit)
                if chain is None:
                    return None
                take = need if need < room else room
            if take <= 0:
                return None
            routes.append((u, v, take, chain))
            for link, direction in chain:
                key = (link, direction)
                residual[key] -= take
            need -= take
            splits += 1
            if splits > MAX_SPLITS:
                return None
            if len(routes) > MAX_ROUTE_RECORDS:
                return None
    return routes


def _recipes_for(routes):
    """Build the shared serial route circuit for the routed walks.

    Leaves are shared per directed link, and every walk prefix is shared as
    well, so the circuit stays small even for large proposals.
    """
    recipes = []
    leaves = {}
    prefixes = {}
    route_ids = []

    def leaf_of(link, direction):
        key = (link, direction)
        node = leaves.get(key)
        if node is None:
            node = len(recipes)
            recipes.append([0, link, direction])
            leaves[key] = node
        return node

    for u, v, count, chain in routes:
        prefix = ()
        node = None
        for link, direction in chain:
            leaf = leaf_of(link, direction)
            previous = node
            prefix = prefix + ((link, direction),)
            if previous is None:
                node = leaf
            else:
                shared = prefixes.get(prefix)
                if shared is None:
                    shared = len(recipes)
                    recipes.append([1, previous, leaf])
                    prefixes[prefix] = shared
                node = shared
            if len(recipes) > MAX_RECIPE_NODES:
                return None, None
        if node is None:
            return None, None
        route_ids.append(node)
    return recipes, route_ids


def _plan_loads(plan, links):
    """Aggregate physical load of a plan, keyed by (link, direction)."""
    recipes = plan["recipes"]
    memo = {}

    def leaves(nid):
        cached = memo.get(nid)
        if cached is not None:
            return cached
        node = recipes[nid]
        if node[0] == 0:
            out = [(node[1], node[2])]
        else:
            out = leaves(node[1]) + leaves(node[2])
        memo[nid] = out
        return out

    loads = {}
    for u, v, count, recipe in plan["routes"]:
        for link, direction in leaves(recipe):
            key = (link, direction)
            loads[key] = loads.get(key, 0) + count
    return loads
